// ListAlertsForOrg lists secret scanning alerts for eligible repositories in an organization, from newest to oldest. The authenticated user must be an administrator or security manager for the organization to use this endpoint. OAuth app tokens and personal access tokens (classic) need the `repo` or `security_events` scope to use this endpoint. If this endpoint is only used with public repositories, the token can use the `public_repo` scope instead.
//
// Parameters:
//
//	org: The organization name. The name is not case sensitive.
//	state: Set to `open` or `resolved` to only list secret scanning alerts in a
//	specific state.
//	secretType: A comma-separated list of secret types to return. All default
//	secret patterns are returned. To return generic patterns, pass the token
//	name(s) in the parameter. See "[Supported secret scanning
//	patterns](https://docs.github.com/code-security/secret-scanning/introduction
//	/supported-secret-scanning-patterns#supported-secrets)" for a complete list
//	of secret types.
//	excludeSecretTypes: A comma-separated list of secret types to exclude from
//	the results. All default secret patterns are returned except those matching
//	the specified types. Cannot be combined with the `secret_type` parameter.
//	See "[Supported secret scanning
//	patterns](https://docs.github.com/code-security/secret-scanning/introduction
//	/supported-secret-scanning-patterns#supported-secrets)" for a complete list
//	of secret types.
//	excludeProviders: A comma-separated list of provider slugs to exclude from
//	the results. Provider slugs use lowercase with underscores (e.g.,
//	`github_secret_scanning`, `clojars`). You can find the provider slug in the
//	`provider_slug` field of each alert. Cannot be combined with the `providers`
//	parameter.
//	providers: A comma-separated list of provider slugs to filter by. Provider
//	slugs use lowercase with underscores (e.g., `github_secret_scanning`,
//	`clojars`). You can find the provider slug in the `provider_slug` field of
//	each alert. Cannot be combined with the `exclude_providers` parameter.
//	resolution: A comma-separated list of resolutions. Only secret scanning
//	alerts with one of these resolutions are listed. Valid resolutions are
//	`false_positive`, `wont_fix`, `revoked`, `pattern_edited`, `pattern_deleted`
//	or `used_in_tests`.
//	assignee: Filters alerts by assignee. Use `*` to get all assigned alerts,
//	`none` to get all unassigned alerts, or a GitHub username to get alerts
//	assigned to a specific user.
//	sort: The property to sort the results by. `created` means when the alert
//	was created. `updated` means when the alert was updated or resolved.
//	direction: The direction to sort the results by.
//	page: The page number of the results to fetch. For more information, see
//	"[Using pagination in the REST
//	API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the
//	-rest-api)."
//	perPage: The number of results per page (max 100). For more information, see
//	"[Using pagination in the REST
//	API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the
//	-rest-api)."
//	before: A cursor, as given in the [Link
//	header](https://docs.github.com/rest/guides/using-pagination-in-the-rest-api
//	#using-link-headers). If specified, the query only searches for events
//	before this cursor. To receive an initial cursor on your first request,
//	include an empty "before" query string.
//	after: A cursor, as given in the [Link
//	header](https://docs.github.com/rest/guides/using-pagination-in-the-rest-api
//	#using-link-headers). If specified, the query only searches for events after
//	this cursor. To receive an initial cursor on your first request, include an
//	empty "after" query string.
//	validity: A comma-separated list of validities that, when present, will
//	return alerts that match the validities in this list. Valid options are
//	`active`, `inactive`, and `unknown`.
//	isPubliclyLeaked: A boolean value representing whether or not to filter
//	alerts by the publicly-leaked tag being present.
//	isMultiRepo: A boolean value representing whether or not to filter alerts by
//	the multi-repo tag being present.
//	hideSecret: A boolean value representing whether or not to hide literal
//	secrets in the results.
//	isBypassed: A boolean value (`true` or `false`) indicating whether to filter
//	alerts by their push protection bypass status. When set to `true`, only
//	alerts that were created because a push protection rule was bypassed will be
//	returned. When set to `false`, only alerts that were not caused by a push
//	protection bypass will be returned.
//	includedMetadata: A comma-separated list of metadata fields to filter alerts
//	by. Only alerts that have all of the specified metadata fields attached will
//	be returned. Possible values are: `owner-email`, `owner-id`, `owner-name`,
//	`secret-id`, `secret-name`, `secret-issued-date`, `secret-expiration-date`,
//	`organization-name`, `organization-id`, `last-used-date`, and
//	`has-organization-access`.
//	ownerEmailHash: Filters alerts to only those whose attached `owner_email`
//	metadata field matches the provided value. The value must be the lowercase
//	hex-encoded SHA-256 hash of the email address to match (for example, the
//	SHA-256 of `user@example.com`). Only alerts that have an `owner_email`
//	metadata value whose SHA-256 hash equals this parameter are returned.
func (sdk *SecretScanningNamespace) ListAlertsForOrg(ctx context.Context, params SecretScanningListAlertsForOrgParams, opts ...RequestOption) ([]OrganizationSecretScanningAlert, error) {
	return SecretScanningListAlertsForOrg(ctx, sdk.config, params, opts...)
}

